                            "<strong>Prøve:</strong> Sett $x = -2$ inn i begge sider:<br><br>V.S: $(-2) + 2 = 0$<br><br>H.S: $-(-2) - 2 = 2 - 2 = 0$<br><br>V.S $=$ H.S ✓<br><br><strong>Svar:</strong> $x = -2$",
