                            "<strong>c)</strong><br>Vi skal løse $4x - (2x + 5) = 11$<br><br>$4x - 2x - 5 = 11$ (løs opp parentesen, husk å bytte fortegn inni)<br><br>$2x - 5 = 11$ (trekk sammen $x$-leddene)<br><br>$2x = 11 + 5$ (flytt tall over og bytt fortegn)<br><br>$2x = 16$ (legg sammen tallene)<br><br>$x = \\frac{16}{2} = 8$ (del på $2$)",
