                            "<strong>b)</strong><br>Vi regner ut steketiden for $m = 2000$.<br><br>$T(2000) = 1.2 \\cdot 2000^{0.55}$ (sett inn $2000$ for $m$)<br><br>$T(2000) \\approx 78.7$ minutter",
