                        "tekst": "<strong>a)</strong> Hva representerer den deriverte?<br><br><strong>b)</strong> Hva kan fortegnet forklare?<br><br><strong>c)</strong> Hvordan finne ekstremalpunkt?",
                        "bilde": null,
                        "hint": "Den deriverte er funksjonens endringshastighet.",
