                        "tekst": "Vi har funksjonen $g(x) = -x^2 + 4x$.<br><br><strong>a)</strong> Finn funksjonens nullpunkter.<br><br><strong>b)</strong> Tegn fortegnslinja for $g(x)$.<br><br><strong>c)</strong> Finn $g'(x)$ og lag en fortegnslinje for denne.<br><br><strong>d)</strong> Beregn $g'(3)$.<br><br><strong>e)</strong> Løs likningen $g'(x) = 0$.",
                        "bilde": null,
                        "hint": "Tegn fortegnslinje for $g'(x)$ ved å finne nullpunktet til den deriverte.",
                        "fasit": null,
                        "fasitSteg": [
                            "<strong>a)</strong><br>Vi finner nullpunktene ved å sette $g(x) = 0$:<br><br>$-x^2 + 4x = 0$<br><br>Vi faktoriserer uttrykket ved å trekke $x$ utenfor en parentes:<br>$x(-x + 4) = 0$<br><br>Dette gir oss to løsninger (når et av leddene er null, er uttrykket null):<br>$x = 0$<br>ELLER<br>$-x + 4 = 0 \\rightarrow x = 4$",
                            "<strong>Svar:</strong> Nullpunktene er $x = 0$ og $x = 4$.",
                            "<strong>b)</strong><br>For å tegne fortegnslinjen for $g(x)$ baserer vi oss på nullpunktene $x = 0$ og $x = 4$. Vi velger testverdier mellom og utenfor disse punktene:<br><br>- $x < 0$ (f.eks. $x = -1$): $g(-1) = -(-1)^2 + 4(-1) = -1 - 4 = -5$ (Negativ, stiplet linje)<br>- $0 < x < 4$ (f.eks. $x = 2$): $g(2) = -(2)^2 + 4(2) = -4 + 8 = 4$ (Positiv, heltrukken linje)<br>- $x > 4$ (f.eks. $x = 5$): $g(5) = -(5)^2 + 4(5) = -25 + 20 = -5$ (Negativ, stiplet linje)",
                            "<strong>Svar:</strong> Fortegnslinjen for $g(x)$ har nullpunkter ved $x = 0$ og $x = 4$. Den er stiplet for $x < 0$, heltrukken for $0 < x < 4$, og stiplet for $x > 4$.",
                            "<strong>c)</strong><br>Vi skal først finne den deriverte funksjonen $g'(x)$:<br><br>$g(x) = -x^2 + 4x$<br>$\\rightarrow g'(x) = -2x^{2-1} + 4 \\cdot 1$ (Bruk regelen for potenser: derivert av $x^n$ er $n \\cdot x^{n-1}$)<br>$\\rightarrow g'(x) = -2x + 4$<br><br>Så finner vi nullpunktet for den deriverte for å lage fortegnslinje:<br>$-2x + 4 = 0$<br>$\\rightarrow 2x = 4$<br>$\\rightarrow x = \\frac{4}{2} = 2$<br><br>Vi tester fortegnet:<br>- For $x < 2$ (f.eks. $x = 0$): $g'(0) = -2(0) + 4 = 4$ (Positiv, heltrukken linje)<br>- For $x > 2$ (f.eks. $x = 3$): $g'(3) = -2(3) + 4 = -2$ (Negativ, stiplet linje)",
                            "<strong>Svar:</strong> $g'(x) = -2x + 4$. Fortegnslinjen for den deriverte har null i $x = 2$, er heltrukken før 2, og stiplet etter.",
                            "<strong>d)</strong><br>Vi setter inn verdien $x = 3$ i den deriverte funksjonen vi fant i c):<br><br>$g'(3) = -2 \\cdot 3 + 4$<br>$\\rightarrow g'(3) = -6 + 4$<br>$\\rightarrow g'(3) = -2$<br><br>Dette forteller oss at grafen til $g(x)$ synker med stigningstall -2 når $x = 3$.",
                            "<strong>Svar:</strong> $g'(3) = -2$",
                            "<strong>e)</strong><br>Vi løser likningen ved å sette uttrykket for $g'(x)$ fra c) lik 0:<br><br>$g'(x) = 0$<br>$-2x + 4 = 0$ (Sett inn uttrykket for $g'(x)$)<br>$2x = 4$ (Flytt $-2x$ over til høyre side for å få et positivt ledd)<br>$x = \\frac{4}{2}$ (Del på 2 på begge sider)<br>$x = 2$<br><br>Denne løsningen gir oss x-verdien der grafen til $g$ har et bunn- eller toppunkt, noe vi også fant i c).",
                            "<strong>Svar:</strong> $x = 2$"
                        ],
                        "starter": ""
